declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Access\User\Application\Service\Visibility\UserVisibilityService;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Service\Visibility\RelyingPartyVisibilityService;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Service\Visibility\TrustedClientVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ClientIdentityRef;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ClientIdentityAttributes;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ClientIdentity;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityFilter;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityCursor;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityReadGateway;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentitySlide;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ClientIdentityVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ClientIdentityReadGateway $readGateway,
        private readonly ClientIdentityWriteGateway $writeGateway,
        private readonly UserVisibilityService $userVisibilityService,
        private readonly RelyingPartyVisibilityService $relyingPartyVisibilityService,
        private readonly TrustedClientVisibilityService $trustedClientVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(ClientIdentity $content): ClientIdentityAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(ClientIdentity $content): ClientIdentityAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(ClientIdentityAttributes $attributes, ?ClientIdentity $original = null): ClientIdentityAttributes
    {
        $this->logDebug("Copy with fixed for Client identity");
        $span = $this->startSpan("Copy with fixed for  Client identity");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new ClientIdentityPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(ClientIdentityAttributes $attributes, ?ClientIdentity $original = null): ClientIdentityAttributes
    {
        $this->logDebug("Copy with hidden for Client identity");
        $span = $this->startSpan("Copy with hidden for  Client identity");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|ClientIdentityRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Client identity");
        $span = $this->startSpan("Check visibility of an iterator for  Client identity");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new ClientIdentityRef($value));
            } elseif ($value instanceof ClientIdentityRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new ClientIdentityFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(ClientIdentityFilter $filter, ?ClientIdentityCursor $cursor = null): ClientIdentitySlide
    {
        $this->logDebug("List visibles for Client identity");
        $span = $this->startSpan("List visibles for  Client identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (ClientIdentity $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(ClientIdentityFilter $filter): int
    {
        $this->logDebug("Count visibles for Client identity");
        $span = $this->startSpan("Count visibles for  Client identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(ClientIdentityFilter $filter, ?ClientIdentityCursor $cursor = null): ClientIdentitySlide
    {
        $this->logDebug("List visibles for update for Client identity");
        $span = $this->startSpan("List visibles for update for  Client identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (ClientIdentity $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(ClientIdentityFilter $filter): int
    {
        $this->logDebug("Count visibles for update for Client identity");
        $span = $this->startSpan("Count visibles for update for  Client identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(ClientIdentityRef $ref): ?ClientIdentity
    {
        $this->logDebug("Retrieve visible for Client identity");
        $span = $this->startSpan("Retrieve visible for  Client identity");
        try {
            $filter = new ClientIdentityFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(ClientIdentityRef $ref): ?ClientIdentity
    {
        $this->logDebug("Retrieve visible for update for Client identity");
        $span = $this->startSpan("Retrieve visible for update for  Client identity");
        try {
            $filter = new ClientIdentityFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?ClientIdentityRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Client identity");
        $span = $this->startSpan("Check fields for fix for Client identity");
        try {
            $result = $this->dispatcher->dispatch(new ClientIdentityCollectNonEditableFields(ClientIdentity::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?ClientIdentityRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for Client identity");
        $span = $this->startSpan("Check fields to hide for  Client identity");
        try {
            $result = $this->dispatcher->dispatch(new ClientIdentityCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(ClientIdentityAttributes $attributes): ClientIdentityAttributes
    {
        $this->logDebug("Check visibility of parent references for Client identity");
        $span = $this->startSpan("Check visibility of parent references for  Client identity");
        try {
            $user = $attributes->getUser();
            if (null !== $user && !$this->userVisibilityService->checkVisibility($user)) {
                throw new NotFoundException("Unknown User " . ($user->uid() ?? 'no-id'));
            }
            $relyingParty = $attributes->getRelyingParty();
            if (null !== $relyingParty && !$this->relyingPartyVisibilityService->checkVisibility($relyingParty)) {
                throw new NotFoundException("Unknown RelyingParty " . ($relyingParty->uid() ?? 'no-id'));
            }
            $trustedClient = $attributes->getTrustedClient();
            if (null !== $trustedClient && !$this->trustedClientVisibilityService->checkVisibility($trustedClient)) {
                throw new NotFoundException("Unknown TrustedClient " . ($trustedClient->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(ClientIdentityFilter $filter): ClientIdentityFilter
    {
        $this->logDebug("Compose visibility filter for Client identity");
        $span = $this->startSpan("Compose visibility filter for  Client identity");
        try {
            $result = $this->dispatcher->dispatch(new ClientIdentityRestrictFilterToVisibility($filter));
            return $result->clientIdentityFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(ClientIdentity $value): bool
    {
        $this->logDebug("Check if item is visible for Client identity");
        $span = $this->startSpan("Check if item is visible for  Client identity");
        try {
            $result = $this->dispatcher->dispatch(new ClientIdentityVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(ClientIdentity $content, bool $inlist): ClientIdentityAttributes
    {
        $this->logDebug("Prepare hydration to visible data for Client identity");
        $span = $this->startSpan("Prepare hydration to visible data for Client identity");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new ClientIdentityEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
